[metadata] {"type": "create", "filePath": "/workspace/repo/src/gcp/ailogic.ts", "content": "import { Client } from "../apiv2";
import { aiLogicOrigin } from "../api";
import { FirebaseError } from "../error";
import * as backend from "../deploy/functions/backend";
import * as events from "../functions/events";

const API_VERSION = "v1beta";

/** The AI Logic API client. */
export const client = new Client({
  urlPrefix: aiLogicOrigin(),
  apiVersion: API_VERSION,
  auth: true,
});

type Endpoint = backend.Endpoint;

/** The request body for creating/updating an AI Logic blocking trigger. */
interface TriggerBody {
  cloudFunction: {
    id: string;
    locationId: string;
  };
}

/**
 * Maps an AI Logic blocking event type to the trigger ID used in API calls.
 */
function triggerIdForEventType(eventType: string): string {
  if (eventType === events.v2.AI_LOGIC_BEFORE_GENERATE_CONTENT) {
    return "before-generate-content";
  }
  if (eventType === events.v2.AI_LOGIC_AFTER_GENERATE_CONTENT) {
    return "after-generate-content";
  }
  throw new FirebaseError(`Received invalid AI Logic blocking trigger event type ${eventType}`);
}

/**
 * Returns the location segment used in the API path. Global triggers (those
 * without the regionalWebhook option) use "global"; regional triggers use the
 * endpoint's region.
 */
function locationForEndpoint(endpoint: Endpoint & backend.BlockingTriggered): string {
  return endpoint.blockingTrigger.options?.regionalWebhook ? endpoint.region : "global";
}

/**
 * Creates a new AI Logic blocking trigger via POST. If the POST fails with an
 * HTTP 409 (conflict), falls back to a PATCH to update the existing trigger.
 * For any other POST failure, the error is thrown without calling PATCH.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function upsertBlockingFunction(endpoint: Endpoint): Promise<void> {
  const ep = endpoint as Endpoint & backend.BlockingTriggered;
  const location = locationForEndpoint(ep);
  const triggerId = triggerIdForEventType(ep.blockingTrigger.eventType);
  const body: TriggerBody = {
    cloudFunction: {
      id: ep.id,
      locationId: ep.region,
    },
  };

  try {
    await client.post<TriggerBody, unknown>(
      `projects/${ep.project}/locations/${location}/triggers`,
      body,
      {
        queryParams: {
          triggerId: triggerId,
          validateOnly: "false",
        },
      },
    );
  } catch (err: any) {
    const statusCode = err?.status ?? err?.context?.response?.statusCode;
    if (statusCode !== 409) {
      throw err;
    }
    await client.patch<TriggerBody, unknown>(
      `projects/${ep.project}/locations/${location}/triggers/${triggerId}`,
      body,
      {
        queryParams: {
          allowMissing: "false",
          validateOnly: "false",
        },
      },
    );
  }
}

/**
 * Deletes an AI Logic blocking trigger. Uses allowMissing: "true" so that the
 * deletion is idempotent.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function deleteBlockingFunction(endpoint: Endpoint): Promise<void> {
  const ep = endpoint as Endpoint & backend.BlockingTriggered;
  const location = locationForEndpoint(ep);
  const triggerId = triggerIdForEventType(ep.blockingTrigger.eventType);
  await client.delete<unknown>(
    `projects/${ep.project}/locations/${location}/triggers/${triggerId}`,
    {
      queryParams: {
        allowMissing: "true",
        validateOnly: "false",
      },
    },
  );
}
